import { Component, ParentComponent } from "solid-js";

import { Activatable, ActivatableProps } from "#core/ui-next/components/activatable.jsx";
import { RadioButtonSize } from "#core/ui-next/components/radio-button.jsx";
import { useScreenFlowContext } from "#core/ui-next/components/screen-flow.jsx";
import { Tab } from "#core/ui-next/components/tab.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

import style from "./create-game-components.scss?url";

export interface CreateGameHRuleComponentProps {
	class?: string;
}

export interface CreateGameHRule2Props {
	color?: string;
	class?: string;
}

export const CreateGameHRule2: Component<CreateGameHRule2Props> = (props) => {
	return (
		<div
			class={props.class}
			style={{ "border-bottom": `1px solid ${props.color ?? "#4545454D"}` }}
		/>
	);
};

const CreateGameHRuleComponent: Component<CreateGameHRuleComponentProps> = (props) => {
	return <div class={`create-game-hrule ${props.class ?? ""}`} />;
};

export const CreateGameHRule = ComponentRegistry.register({
	name: "CreateGameHRule",
	createInstance: CreateGameHRuleComponent,
	styles: [style],
});

export interface CreateGameBackButtonProps {
	class?: string;
	onBack?: () => void;
}

const CreateGameBackButtonComponent: Component<CreateGameBackButtonProps> = (props) => {
	const context = useScreenFlowContext();

	return (
		<Activatable
			onActivate={() => (props.onBack ? props.onBack() : context.activatePrev())}
			class="relative"
			name="CreateGameBackButton"
			disableFocus={true}
			hotkeyAction="cancel"
			navTrayText="LOC_GENERIC_BACK"
			audio={{
				onPress: "data-audio-back-press",
				onActivate: "data-audio-back-activate",
			}}
		>
			<div class={`p-1 border-2 border-secondary-3 bg-accent-6 ${props.class ?? ""}`}>
				<div class="create-game-back-button size-11" />
			</div>
		</Activatable>
	);
};

export const CreateGameBackButtton = ComponentRegistry.register({
	name: "CreateGameBackButton",
	createInstance: CreateGameBackButtonComponent,
	styles: [style],
});

const CreateGameNavButtonComponent: ParentComponent<ActivatableProps> = (props) => {
	return (
		<Activatable
			class={`create-game-nav-button-outer p-1 border-2 border-secondary-3 bg-accent-6 ${props.class ?? ""}`}
			name="CreateGameNavButton"
			disableFocus={props.disableFocus}
			hotkeyAction={props.hotkeyAction}
			onActivate={props.onActivate}
			disabled={props.disabled}
			navTrayText={props.navTrayText}
		>
			<div class="create-game-nav-button-inner border-2 h-11 w-40 relative flex items-center justify-center">
				<div class=" fxs-header uppercase text-lg font-title">{props.children}</div>
			</div>
		</Activatable>
	);
};

export const CreateGameNavButton = ComponentRegistry.register({
	name: "CreateGameNavButton",
	createInstance: CreateGameNavButtonComponent,
	styles: [style],
});

const CreateGameTabPipsComponent: Component = () => {
	return (
		<div class="flex flex-col">
			<div class="create-game-tab-pips-hrule mb-1" />
			<div class="create-game-tab-pips-bg">
				<Tab.TabListPips size={RadioButtonSize.SMALL} />
			</div>
			<div class="create-game-tab-pips-hrule mt-1" />
		</div>
	);
};

export const CreateGameTabPips = ComponentRegistry.register({
	name: "CreateGameTabPips",
	createInstance: CreateGameTabPipsComponent,
});
